/**
 * OpenAI Mock for Jest - PREVENTS ALL REAL API CALLS
 * This is a comprehensive mock that intercepts all OpenAI API calls
 * and returns deterministic test responses without making network requests.
 */

import { jest } from '@jest/globals';

// Deterministic mock responses
const mockChatCompletion = {
  id: 'chatcmpl-mock-test',
  object: 'chat.completion',
  created: Math.floor(Date.now() / 1000),
  model: 'gpt-3.5-turbo',
  choices: [{
    index: 0,
    message: {
      role: 'assistant',
      content: 'Mock AI response - no real API call made'
    },
    finish_reason: 'stop'
  }],
  usage: {
    prompt_tokens: 10,
    completion_tokens: 15,
    total_tokens: 25
  }
};

const mockEmbedding = {
  object: 'list',
  data: [{
    object: 'embedding',
    embedding: Array.from({ length: 1536 }, () => Math.random() * 0.1),
    index: 0
  }],
  model: 'text-embedding-3-small',
  usage: {
    prompt_tokens: 5,
    total_tokens: 5
  }
};

// Create shared mock functions that can be inspected in tests
export const mockChatCreate = jest.fn().mockResolvedValue(mockChatCompletion);
export const mockEmbeddingCreate = jest.fn().mockResolvedValue(mockEmbedding);

// Mock OpenAI instance that all services will receive
export const mockOpenAIInstance = {
  chat: {
    completions: {
      create: mockChatCreate
    }
  },
  embeddings: {
    create: mockEmbeddingCreate
  }
};

// Mock OpenAI constructor with SECURITY CHECK
const MockOpenAI = jest.fn().mockImplementation((config) => {
  // CRITICAL SECURITY CHECK - Block real API keys
  if (config?.apiKey && !config.apiKey.includes('test') && !config.apiKey.includes('mock')) {
    const error = new Error(`SECURITY VIOLATION: Real API key detected in tests: ${config.apiKey.substring(0, 8)}...`);
    console.error('[OPENAI MOCK]', error.message);
    throw error;
  }
  
  return mockOpenAIInstance;
});

// Export the mock as default (this is what import OpenAI will get)
export default MockOpenAI;

// Export named export for ES modules
export { MockOpenAI as OpenAI };

// Export mock data for tests
export { mockChatCompletion, mockEmbedding };

// Log that mock is active
if (process.env.NODE_ENV === 'test') {
  console.log('[OPENAI MOCK] Active - All OpenAI API calls will be intercepted and mocked');
}